const result = $input.item.json;
if (!result || !result.valid) {
  return null;
}
return { json: $('LINE Webhook').first().json };

const data = $input.item.json;
const body = data.body || {};
const events = body.events || [];
if (events.length === 0) return null;
const event = events[0];
if (event.type !== 'message' || !event.message || event.message.type !== 'text') return null;
return {
  json: {
    lineUserId: event.source && event.source.userId || '',
    messageText: event.message.text || '',
    replyToken: event.replyToken || ''
  }
};

const parsedMsg = $('Parse Message').first().json;
const text = parsedMsg.messageText || '';
const sessionData = $input.item.json;
const mode = sessionData.mode || null;

let intent = 'qa';
let keyword = '';
let fileType = '';
let askFileName = '';

const FILE_TYPE_MAP = { 'PDF': 'pdf', 'Word': 'docx', 'Excel': 'xlsx', 'JPG': 'jpg' };

// 保留關鍵字優先於 session mode（點選 Quick Reply 固定按鈕時）
if (text === '找檔案') {
  intent = 'file_search_menu';
} else if (text === '問問題') {
  intent = 'qa';
} else if (text.startsWith('問:')) {
  intent = 'ask_about_file';
  askFileName = text.slice(2).trim();
} else if (mode && mode.startsWith('asking_about:')) {
  intent = 'file_qa';
  askFileName = mode.slice('asking_about:'.length);
  keyword = text;
} else if (mode === 'waiting_filetype') {
  const selectedType = FILE_TYPE_MAP[text];
  if (selectedType) {
    intent = 'file_type_selected';
    fileType = selectedType;
  } else {
    intent = 'qa';
  }
} else if (mode && mode.startsWith('waiting_keyword:')) {
  intent = 'file_search_execute';
  keyword = text;
  fileType = mode.split(':')[1];
} else {
  intent = 'qa';
}

return {
  json: {
    lineUserId: parsedMsg.lineUserId,
    messageText: text,
    replyToken: parsedMsg.replyToken,
    sessionMode: mode,
    sessionTurns: sessionData.turns || [],
    intent,
    keyword,
    fileType,
    askFileName,
  }
};

const authResult = $input.item.json;
const intentData = $('Intent Router').first().json;

if (!authResult.authorized) {
  try {
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.line.me/v2/bot/message/reply',
      headers: {
        'Authorization': 'Bearer zfUhwyDkW+q8PbPReXde6cN7d5g0EDaoRLiJN5q8x1mw15Sy4M19MqZRafcrheFOUfu+26krT110NoFELUjJWgB5pSnzRzoOh8w9oJu75Fzcnx126tN0gS1te8GtRzxkiFqHC6zmAFvfDuCFMaR/0gdB04t89/1O/w1cDnyilFU=',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        replyToken: intentData.replyToken,
        messages: [{ type: 'text', text: '\u60a8\u7121\u4f7f\u7528\u6b0a\u9650' }]
      })
    });
  } catch(e) {}
  return null;
}

// Authorized - pass intent data through
return {
  json: {
    lineUserId: intentData.lineUserId,
    messageText: intentData.messageText,
    replyToken: intentData.replyToken,
    sessionMode: intentData.sessionMode,
    sessionTurns: intentData.sessionTurns,
    intent: intentData.intent,
    keyword: intentData.keyword,
    fileType: intentData.fileType,
    askFileName: intentData.askFileName,
  }
};

const resp = $input.item.json;
let chunks = (resp && Array.isArray(resp.chunks)) ? resp.chunks : (Array.isArray(resp) ? resp : []);
const msgData = $('Parse Message').first().json;
return {
  json: {
    lineUserId: msgData.lineUserId,
    messageText: msgData.messageText,
    replyToken: msgData.replyToken,
    chunks: chunks,
    chunkIds: chunks.map(function(c) { return c.chunk_id; })
  }
};

const chunksData = $input.item.json;
// Get session turns from the early session query (via Intent Router)
const intentData = $('Intent Router').first().json;
const turns = Array.isArray(intentData.sessionTurns) ? intentData.sessionTurns : [];
const history = turns.slice(-6); // last 3 rounds

return {
  json: {
    lineUserId: chunksData.lineUserId,
    messageText: chunksData.messageText,
    replyToken: chunksData.replyToken,
    chunks: chunksData.chunks,
    chunkIds: chunksData.chunkIds,
    history: history,
    sessionTurns: turns
  }
};

const promptData = $input.item.json;
if (!promptData || promptData.error) {
  throw new Error('prompt_builder API failed: ' + (promptData && promptData.error || 'Unknown error'));
}
const prevData = $('Combine QA Data').first().json;
return {
  json: {
    lineUserId: prevData.lineUserId,
    messageText: prevData.messageText,
    replyToken: prevData.replyToken,
    chunkIds: prevData.chunkIds,
    sessionTurns: prevData.sessionTurns,
    systemPrompt: promptData.system || '',
    userPrompt: promptData.prompt || ''
  }
};

const response = $input.item.json;
const answer = (response.message && response.message.content) || response.response || '抱歉，目前無法生成回答，請稍後再試。';
const prevData = $('Parse Prompt').first().json;

// Build LINE reply body here (not in HTTP Request) to avoid emoji in n8n expression parser
const replyBody = JSON.stringify({
  to: prevData.lineUserId,
  messages: [{
    type: 'text',
    text: answer,
    quickReply: {
      items: [
        { type: 'action', action: { type: 'message', label: '\uD83D\uDD0D \u627E\u6A94\u6848', text: '\u627E\u6A94\u6848' } },
        { type: 'action', action: { type: 'message', label: '\uD83D\uDCAC \u554F\u554F\u984C', text: '\u554F\u554F\u984C' } }
      ]
    }
  }]
});

return {
  json: {
    lineUserId: prevData.lineUserId,
    messageText: prevData.messageText,
    to: prevData.lineUserId,
    chunkIds: prevData.chunkIds,
    sessionTurns: prevData.sessionTurns,
    answer: answer,
    replyBody: replyBody
  }
};

const extractData = $('Extract Answer').first().json;
const oldTurns = Array.isArray(extractData.sessionTurns) ? extractData.sessionTurns : [];
const newTurns = oldTurns.concat([
  { role: 'user', content: extractData.messageText },
  { role: 'assistant', content: extractData.answer }
]).slice(-10);

const chunkIds = Array.isArray(extractData.chunkIds) ? extractData.chunkIds : [];
const chunkIdsArray = chunkIds.length > 0 ? '{' + chunkIds.join(',') + '}' : '{}';

return {
  json: {
    lineUserId: extractData.lineUserId,
    messageText: extractData.messageText,
    answer: extractData.answer,
    newTurnsJson: JSON.stringify(newTurns),
    chunkIdsArray: chunkIdsArray
  }
};

const PUBLIC_API_BASE_URL = 'https://quadruplication-satisfyingly-corrina.ngrok-free.dev';

const resp = $input.item.json;
const intentData = $('Intent Router').first().json;
const results = (resp && Array.isArray(resp.results)) ? resp.results : [];
const keyword = intentData.keyword || '';

var message;

if (results.length === 0) {
  message = {
    type: 'text',
    text: '找不到包含「' + keyword + '」的檔案。\n\n請嘗試其他關鍵字，或輸入「找檔案」重試。'
  };
} else {
  var fileRows = results.slice(0, 10).map(function(r, i) {
    var url = PUBLIC_API_BASE_URL + r.download_url;
    var displayName = (i + 1) + '. ' + r.file_name;
    return {
      type: 'box',
      layout: 'horizontal',
      spacing: 'sm',
      margin: 'sm',
      contents: [
        {
          type: 'text',
          text: displayName,
          wrap: true,
          flex: 4,
          size: 'sm',
          color: '#1a73e8',
          decoration: 'underline',
          action: {
            type: 'uri',
            label: '下載',
            uri: url
          }
        },
        {
          type: 'button',
          style: 'secondary',
          height: 'sm',
          flex: 2,
          action: {
            type: 'message',
            label: '問',
            text: '問:' + r.file_name
          }
        }
      ]
    };
  });

  var flexContent = {
    type: 'bubble',
    header: {
      type: 'box',
      layout: 'vertical',
      backgroundColor: '#1DB446',
      contents: [
        {
          type: 'text',
          text: '找到 ' + results.length + ' 個相關檔案',
          color: '#ffffff',
          weight: 'bold',
          size: 'md'
        }
      ]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      spacing: 'none',
      contents: fileRows
    }
  };

  if (results.length > 10) {
    flexContent.footer = {
      type: 'box',
      layout: 'vertical',
      contents: [
        {
          type: 'text',
          text: '（共 ' + results.length + ' 筆，顯示前 10 筆）',
          size: 'xs',
          color: '#999999',
          align: 'center'
        }
      ]
    };
  }

  message = {
    type: 'flex',
    altText: '找到 ' + results.length + ' 個相關檔案',
    contents: flexContent
  };
}

var replyBody = JSON.stringify({
  replyToken: intentData.replyToken,
  messages: [message]
});

return {
  json: {
    lineUserId: intentData.lineUserId,
    replyToken: intentData.replyToken,
    replyText: '找到 ' + results.length + ' 個相關檔案',
    replyBody: replyBody
  }
};

const intentData = $('Intent Router').first().json;
// Build reply with Quick Reply file type buttons (using unicode to avoid emoji parse issues)
const replyBody = JSON.stringify({
  replyToken: intentData.replyToken,
  messages: [{
    type: 'text',
    text: '\u8ACB\u9078\u64C7\u67E5\u8A62\u6A94\u6848\u985E\u578B\uFF1A',
    quickReply: {
      items: [
        { type: 'action', action: { type: 'message', label: 'PDF', text: 'PDF' } },
        { type: 'action', action: { type: 'message', label: 'Word', text: 'Word' } },
        { type: 'action', action: { type: 'message', label: 'Excel', text: 'Excel' } },
        { type: 'action', action: { type: 'message', label: 'JPG', text: 'JPG' } }
      ]
    }
  }]
});
return { json: { replyToken: intentData.replyToken, lineUserId: intentData.lineUserId, replyBody: replyBody } };

const intentData = $('Intent Router').first().json;
const typeLabel = { 'pdf': 'PDF', 'docx': 'Word', 'xlsx': 'Excel', 'jpg': 'JPG' }[intentData.fileType] || intentData.fileType;
const replyBody = JSON.stringify({
  replyToken: intentData.replyToken,
  messages: [{ type: 'text', text: '\u8ACB\u8F38\u5165\u8981\u641C\u5C0B\u7684 ' + typeLabel + ' \u6A94\u6848\u95DC\u9375\u5B57\uFF1A' }]
});
return { json: { lineUserId: intentData.lineUserId, fileType: intentData.fileType, replyBody: replyBody } };

const ir = $('Intent Router').first().json;
const fname = ir.askFileName || '';
const replyBody = JSON.stringify({
  replyToken: ir.replyToken,
  messages: [{
    type: 'text',
    text: '\u60a8\u60f3\u554f\u95dc\u65bc\u300c' + fname + '\u300d\u7684\u4ec0\u9ebc\u554f\u984c\uff1f',
    quickReply: {
      items: [
        { type: 'action', action: { type: 'message', label: '\uD83D\uDD0D \u627e\u6a94\u6848', text: '\u627e\u6a94\u6848' } },
        { type: 'action', action: { type: 'message', label: '\uD83D\uDCAC \u554f\u554f\u984c', text: '\u554f\u554f\u984c' } }
      ]
    }
  }]
});
return { json: { lineUserId: ir.lineUserId, replyToken: ir.replyToken, replyBody } };
